import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String x = scanner.nextLine();
        int i = 1;
        boolean replacedAt = false;
        while (i < x.length()) {
            if (i + 1 < x.length() && x.substring(i, i + 2).equals("at")) {
                x = x.substring(0, i) + "@" + x.substring(i + 2);
                replacedAt = true;
                break;
            }
            i++;
        }
        x = x.replace("dot", ".");
        if (x.startsWith(".")) {
            x = "dot" + x.substring(1);
        }
        if (x.endsWith(".")) {
            x = x.substring(0, x.length() - 1) + "dot";
        }
        System.out.println(x);
    }
}
